   222  /*  For following MacOS file naming convention */
   223  static const char *
   224  getseparator (const char *f)
   225  {
   226      const char *p = 0;
   227      const char *q = 0;
   228      char c = 0;;
   229
   230      p = NULL;
   231      q = f;
   232      do  {
   233          c = *q++;
   234          if (c == '\\' || c == '/' || c == ':') {
   235              p = q;
   236          }
   237      } while (c);
   238      return p;
   239  }
