   906  generic_rel_from_rel32(
   907      dwarf_elf_object_access_internals_t *ep,
   908      struct generic_shdr * gsh,
   909      dw_elf32_rel *relp,
   910      struct generic_rela *grel,int *errcode)
   911  {
   912      Dwarf_Unsigned ecount = 0;
   913      Dwarf_Unsigned size = gsh->gh_size;
   914      Dwarf_Unsigned size2 = 0;
   915      Dwarf_Unsigned i = 0;
   916
   917      ecount = size/sizeof(dw_elf32_rel);
   918      size2 = ecount * sizeof(dw_elf32_rel);
   919      if (size != size2) {
   920          *errcode = DW_DLE_SECTION_SIZE_ERROR;
   921          return  DW_DLV_ERROR;
   922      }
   923      for ( i = 0; i < ecount; ++i,++relp,++grel) {
   924          ASNAR(ep->f_copy_word,grel->gr_offset,relp->r_offset);
   925          ASNAR(ep->f_copy_word,grel->gr_info,relp->r_info);
   926          grel->gr_addend  = 0; /* Unused for plain .rel */
   927          grel->gr_sym  = grel->gr_info >>8; /* ELF32_R_SYM */
   928          grel->gr_is_rela = FALSE;
   929          grel->gr_type = grel->gr_info & 0xff;
   930      }
   931      return DW_DLV_OK;
   932  }
