   934  static int
   935  generic_rel_from_rel64(
   936      dwarf_elf_object_access_internals_t *ep,
   937      struct generic_shdr * gsh,
   938      dw_elf64_rel *relp,
   939      struct generic_rela *grel,int *errcode)
   940  {
   941      Dwarf_Unsigned ecount = 0;
   942      Dwarf_Unsigned size = gsh->gh_size;
   943      Dwarf_Unsigned size2 = 0;
   944      Dwarf_Unsigned i = 0;
   945      int objlittleendian = (ep->f_endian == DW_END_little);
   946      int ismips64 = (ep->f_machine == EM_MIPS);
   947      int issparcv9 = (ep->f_machine == EM_SPARCV9);
   948
   949      ecount = size/sizeof(dw_elf64_rel);
   950      size2 = ecount * sizeof(dw_elf64_rel);
   951      if (size != size2) {
   952          *errcode = DW_DLE_SECTION_SIZE_ERROR;
   953          return DW_DLV_ERROR;
   954      }
   955      for ( i = 0; i < ecount; ++i,++relp,++grel) {
   956          ASNAR(ep->f_copy_word,grel->gr_offset,relp->r_offset);
   957          ASNAR(ep->f_copy_word,grel->gr_info,relp->r_info);
   958          grel->gr_addend  = 0; /* Unused for plain .rel */
   959          if (ismips64 && objlittleendian ) {
   960              char realsym[4];
   961
   962              memcpy(realsym,&relp->r_info,sizeof(realsym));
   963              ASNAR(ep->f_copy_word,grel->gr_sym,realsym);
   964              grel->gr_type  = relp->r_info[7];
   965              grel->gr_type2 = relp->r_info[6];
   966              grel->gr_type3 = relp->r_info[5];
   967          } else if (issparcv9) {
   968              /*  Always Big Endian?  */
   969              char realsym[4];
   970
   971              memcpy(realsym,&relp->r_info,sizeof(realsym));
   972              ASNAR(ep->f_copy_word,grel->gr_sym,realsym);
   973              grel->gr_type  = relp->r_info[7];
   974          } else {
   975              grel->gr_sym  = grel->gr_info >>32;
   976              grel->gr_type = grel->gr_info & 0xffffffff;
   977          }
   978          grel->gr_is_rela = FALSE;
   979      }
   980      return DW_DLV_OK;
   981  }
